import 'dart:typed_data';
import 'package:supabase_flutter/supabase_flutter.dart';
import '../../../services/supabase_service.dart';

class ManoxPost { final String id,creatorName,handle,text; final int likes,comments; final String? imageUrl,avatarUrl,ownerUserId; final String contentType; final bool likedByMe,savedByMe,allowComments,allowDownloads; const ManoxPost({required this.id,required this.creatorName,required this.handle,required this.text,required this.likes,required this.comments,required this.likedByMe,required this.savedByMe,this.imageUrl,this.avatarUrl,this.contentType='post',this.ownerUserId,this.allowComments=true,this.allowDownloads=true}); }
class ManoxComment { final String id,userName,body; final DateTime createdAt; const ManoxComment({required this.id,required this.userName,required this.body,required this.createdAt}); }
class ManoxSavedItem { final String contentId,folderName; final DateTime createdAt; const ManoxSavedItem({required this.contentId,required this.folderName,required this.createdAt}); }
class ManoxFeedPage { final List<ManoxPost> posts; final String? nextPublishedAt; final String? nextId; final bool hasMore; const ManoxFeedPage({required this.posts,this.nextPublishedAt,this.nextId,required this.hasMore}); }
class SupabasePostRepository {
  static const int _maxImageBytes = 10 * 1024 * 1024;
  static const int _maxVideoBytes = 100 * 1024 * 1024;
  static const Map<String, String> _imageMimeByExtension = {
    'jpg': 'image/jpeg', 'jpeg': 'image/jpeg', 'png': 'image/png', 'webp': 'image/webp', 'gif': 'image/gif',
  };
  static const Map<String, String> _videoMimeByExtension = {
    'mp4': 'video/mp4', 'mov': 'video/quicktime', 'm4v': 'video/x-m4v', 'webm': 'video/webm', '3gp': 'video/3gpp',
  };
  SupabaseClient get _client { final client=SupabaseService.client; if(client==null)throw StateError('MANOX backend is not configured.'); return client; }
  String get _userId { final id=_client.auth.currentUser?.id; if(id==null)throw StateError('Please sign in first.'); return id; }
  Future<bool> isOwner(String contentId) async { final row=await _client.from('contents').select('owner_user_id').eq('id',contentId).maybeSingle(); return row!=null&&row['owner_user_id']==_userId; }
  Future<bool> isSaved(String contentId) async { final row=await _client.from('saved_contents').select('content_id').eq('profile_id',_userId).eq('content_id',contentId).maybeSingle(); return row!=null; }
  Future<bool> isFollowing(String followeeId) async { final target=followeeId.trim(); if(target.isEmpty||target==_userId)return false; final row=await _client.from('profile_follows').select('follower_id').eq('follower_id',_userId).eq('following_id',target).maybeSingle(); return row!=null; }
  Future<bool> toggleFollow(String followeeId,{required bool currentlyFollowing}) async { final target=followeeId.trim(); if(target.isEmpty)throw ArgumentError('Follow target is required.'); if(target==_userId)throw StateError('You cannot follow yourself.'); if(currentlyFollowing){await _client.from('profile_follows').delete().eq('follower_id',_userId).eq('following_id',target);return false;} await _client.from('profile_follows').insert({'follower_id':_userId,'following_id':target}); return true; }
  Future<int> followerCount(String userId) async { final rows=await _client.from('profile_follows').select('follower_id').eq('following_id',userId.trim()); return (rows as List).length; }
  Future<int> followingCount(String userId) async { final rows=await _client.from('profile_follows').select('follower_id').eq('follower_id',userId.trim()); return (rows as List).length; }
  Future<void> saveContent(String contentId,{String folderName='Watch later'}) async { if(!{'Watch later','Important','Helpful'}.contains(folderName))throw ArgumentError('Invalid save folder.'); await _client.from('saved_contents').upsert({'profile_id':_userId,'content_id':contentId,'folder_name':folderName},onConflict:'profile_id,content_id'); }
  Future<void> unsaveContent(String contentId) async=>_client.from('saved_contents').delete().eq('profile_id',_userId).eq('content_id',contentId);
  Future<List<ManoxSavedItem>> fetchSavedItems({String? folderName}) async { var q=_client.from('saved_contents').select('content_id,folder_name,created_at').eq('profile_id',_userId); if(folderName!=null)q=q.eq('folder_name',folderName); final rows=await q.order('created_at',ascending:false); return(rows as List).map((r)=>ManoxSavedItem(contentId:r['content_id'] as String,folderName:r['folder_name'] as String,createdAt:DateTime.parse(r['created_at'] as String))).toList(); }
  Future<Set<String>> _fetchSavedIdsForContent(List rows) async { final contentIds=rows.map((row)=>(row['id'] as String)).toSet().toList(); if(contentIds.isEmpty)return <String>{}; final savedRows=await _client.from('saved_contents').select('content_id').eq('profile_id',_userId).inFilter('content_id',contentIds); return (savedRows as List).map((row)=>row['content_id'] as String).toSet(); }
  Future<Set<String>> _fetchLikedIdsForContent(List rows) async { final contentIds=rows.map((row)=>(row['id'] as String)).toSet().toList(); if(contentIds.isEmpty)return <String>{}; final likedRows=await _client.from('content_likes').select('content_id').eq('user_id',_userId).inFilter('content_id',contentIds); return (likedRows as List).map((row)=>row['content_id'] as String).toSet(); }
  Future<List<String>> fetchSaveFolders() async=>['Watch later','Important','Helpful'];
  Future<List<ManoxPost>> _mapRows(List rows) async {
    final savedIds=await _fetchSavedIdsForContent(rows);
    final likedIds=await _fetchLikedIdsForContent(rows);
    return rows.map((row){
      final likeCount=((row['content_likes'] as List?)?.firstOrNull?['count'] as num?)?.toInt()??0;
      final commentCount=((row['content_comments'] as List?)?.firstOrNull?['count'] as num?)?.toInt()??0;
      final profile=row['profiles'] as Map<String,dynamic>?;
      final mediaUrls=List<dynamic>.from(row['media_urls']??const[]);
      final rawUsername=(profile?['username'] as String?)??'creator';
      return ManoxPost(id:row['id'] as String,creatorName:(profile?['display_name'] as String?)??'MANOX Creator',handle:'@${rawUsername.replaceFirst(RegExp(r'^@+'), '')}',text:(row['description'] as String?)??'',likes:likeCount,comments:commentCount,likedByMe:likedIds.contains(row['id']),savedByMe:savedIds.contains(row['id']),contentType:(row['content_type'] as String?)??'post',imageUrl:mediaUrls.isNotEmpty?mediaUrls.first as String:row['media_url'] as String?,avatarUrl:profile?['avatar_url'] as String?,ownerUserId:row['owner_user_id'] as String?,allowComments:(row['allow_comments'] as bool?)??true,allowDownloads:(row['allow_downloads'] as bool?)??true);
    }).toList();
  }
  String get _contentSelect=>'id, owner_user_id, description, media_url, media_urls, content_type, created_at, published_at, allow_comments, allow_downloads, profiles!contents_owner_user_id_fkey(username, display_name, avatar_url), content_likes(count), content_comments(count)';
  Future<ManoxFeedPage> fetchFeedPage({String? beforePublishedAt,String? beforeId,int pageSize=20}) async {
    final size=pageSize.clamp(1,50);
    var q=_client.from('contents').select(_contentSelect).eq('status','published').inFilter('visibility',['public','followers']).eq('audience_category','general');
    if(beforePublishedAt!=null&&beforeId!=null){ q=q.or('published_at.lt.$beforePublishedAt,and(published_at.eq.$beforePublishedAt,id.lt.$beforeId)'); }
    final rows=await q.order('published_at',ascending:false,nullsFirst:false).order('id',ascending:false).limit(size+1) as List;
    final hasMore=rows.length>size;
    final pageRows=hasMore?rows.take(size).toList():rows;
    final posts=await _mapRows(pageRows);
    if(posts.isEmpty)return const ManoxFeedPage(posts:[],hasMore:false);
    final last=pageRows.last as Map<String,dynamic>;
    return ManoxFeedPage(posts:posts,nextPublishedAt:last['published_at'] as String?,nextId:last['id'] as String?,hasMore:hasMore);
  }
  Future<List<ManoxPost>> fetchFeed() async => (await fetchFeedPage()).posts;
  Future<List<ManoxPost>> fetchBeats({bool kidsMode=false,String? kidsCategory}) async {var q=_client.from('contents').select(_contentSelect).eq('status','published').eq('visibility','public').eq('content_type','beat').eq('audience_category',kidsMode?'kids_15_plus':'general');if(kidsMode&&kidsCategory!=null&&kidsCategory.isNotEmpty)q=q.eq('kids_category',kidsCategory);final rows=await q.order('published_at',ascending:false,nullsFirst:false).limit(50);return _mapRows(rows as List);}
  Future<List<ManoxPost>> fetchKidsContent({String? category}) async {var q=_client.from('contents').select(_contentSelect).eq('status','published').eq('audience_category','kids_15_plus');if(category!=null&&category.isNotEmpty)q=q.eq('kids_category',category);final rows=await q.order('published_at',ascending:false,nullsFirst:false).limit(50);return _mapRows(rows as List);}
  Future<List<ManoxPost>> fetchMyPosts() async=>fetchPostsByOwner(_userId);
  Future<List<ManoxPost>> fetchPostsByOwner(String ownerUserId) async {final rows=await _client.from('contents').select(_contentSelect).eq('owner_user_id',ownerUserId).eq('status','published').eq('audience_category','general').order('created_at',ascending:false).limit(50);return _mapRows(rows as List);}
  Future<String?> uploadImage(Uint8List bytes,String extension,String? mimeType) async { final ext=extension.toLowerCase().replaceAll('.',''); final expectedMime=_imageMimeByExtension[ext]; if(expectedMime==null)throw ArgumentError('Unsupported image format. Use JPG, PNG, WEBP or GIF.'); if(bytes.isEmpty)throw StateError('Selected image is empty.'); if(bytes.length>_maxImageBytes)throw ArgumentError('Image must be 10 MB or smaller.'); if(mimeType!=null&&mimeType.isNotEmpty&&mimeType.toLowerCase()!=expectedMime)throw ArgumentError('Image MIME type does not match its file extension.'); return _uploadMedia(bytes,ext,expectedMime,_maxImageBytes); }
  Future<String?> uploadVideo(Uint8List bytes,String extension,String? mimeType) async {final ext=extension.toLowerCase().replaceAll('.','');final expectedMime=_videoMimeByExtension[ext];if(expectedMime==null)throw ArgumentError('Unsupported video format. Use MP4, MOV, M4V, WEBM or 3GP.');if(bytes.isEmpty)throw StateError('Selected video is empty.');if(bytes.length>_maxVideoBytes)throw ArgumentError('Video must be 100 MB or smaller.');if(mimeType!=null&&mimeType.isNotEmpty&&mimeType.toLowerCase()!=expectedMime)throw ArgumentError('Video MIME type does not match its file extension.');return _uploadMedia(bytes,ext,expectedMime,_maxVideoBytes);}
  Future<String?> _uploadMedia(Uint8List bytes,String extension,String mimeType,int maxBytes) async {if(bytes.isEmpty)throw StateError('Selected media is empty.');if(bytes.length>maxBytes)throw ArgumentError('Selected media exceeds the allowed size.');final path='$_userId/${DateTime.now().microsecondsSinceEpoch}.$extension';await _client.storage.from('manox-media').uploadBinary(path,bytes,fileOptions:FileOptions(contentType:mimeType,upsert:false,cacheControl:'3600'));return path;}
  Future<ManoxPost> createPost({required String text,String? imagePath,String mediaType='post',String audienceCategory='general',String? creatorSkill,String? kidsCategory,String visibility='public',bool allowComments=true,bool allowDownloads=true}) async {final type=mediaType.trim().isEmpty?'post':mediaType.trim();if(type=='beat'&&imagePath==null)throw ArgumentError('A BEAT must contain video media.');final audience=audienceCategory=='kids_15_plus'?'kids_15_plus':'general';if(audience=='kids_15_plus'&&(kidsCategory==null||kidsCategory.trim().isEmpty))throw StateError('Select a Kids category before publishing.');final safeVisibility={'public','followers','private'}.contains(visibility)?visibility:'public';final row=await _client.from('contents').insert({'owner_user_id':_userId,'content_type':type,'description':text,'media_url':imagePath,'media_urls':imagePath==null?<String>[]:<String>[imagePath],'status':'published','visibility':safeVisibility,'audience_category':audience,'creator_skill':creatorSkill,'kids_category':audience=='kids_15_plus'?kidsCategory:null,'allow_comments':allowComments,'allow_downloads':allowDownloads,'published_at':DateTime.now().toIso8601String()}).select('id').single();final id=row['id'] as String;final post=await _client.from('contents').select(_contentSelect).eq('id',id).single();final profile=post['profiles'] as Map<String,dynamic>?;final urls=post['media_urls'] as List?;final username=(profile?['username'] as String?)??'you';return ManoxPost(id:id,creatorName:(profile?['display_name'] as String?)??'You',handle:'@${username.replaceFirst(RegExp(r'^@+'),'')}',text:(post['description'] as String?)??'',likes:0,comments:0,likedByMe:false,savedByMe:false,contentType:(post['content_type'] as String?)??type,imageUrl:urls?.isNotEmpty==true?urls!.first as String:post['media_url'] as String?,avatarUrl:profile?['avatar_url'] as String?,ownerUserId:post['owner_user_id'] as String?,allowComments:(post['allow_comments'] as bool?)??allowComments,allowDownloads:(post['allow_downloads'] as bool?)??allowDownloads);}
  Future<void> updatePost(String contentId,String text) async=>_client.from('contents').update({'description':text.trim(),'updated_at':DateTime.now().toIso8601String()}).eq('id',contentId).eq('owner_user_id',_userId);
  Future<void> deletePost(String contentId) async=>_client.from('contents').delete().eq('id',contentId).eq('owner_user_id',_userId);
  Future<void> toggleLike(String contentId,bool currentlyLiked) async {if(currentlyLiked){await _client.from('content_likes').delete().eq('content_id',contentId).eq('user_id',_userId);return;}await _client.from('content_likes').insert({'content_id':contentId,'user_id':_userId});}
  Future<List<ManoxComment>> fetchComments(String contentId,{int limit=50}) async {final safeLimit=limit.clamp(1,100);final rows=await _client.from('content_comments').select('id, body, created_at, profiles!content_comments_user_id_fkey(display_name)').eq('content_id',contentId).eq('status','visible').order('created_at',ascending:false).limit(safeLimit);final list=(rows as List).map((row){final profile=row['profiles'] as Map<String,dynamic>?;return ManoxComment(id:row['id'] as String,userName:(profile?['display_name'] as String?)??'MANOX User',body:row['body'] as String,createdAt:DateTime.parse(row['created_at'] as String));}).toList();return list.reversed.toList();}
  Future<void> addComment(String contentId,String body) async {final trimmed=body.trim();if(trimmed.isEmpty)return;if(trimmed.length>1000)throw ArgumentError('Comment must be 1000 characters or fewer.');await _client.from('content_comments').insert({'content_id':contentId,'user_id':_userId,'body':trimmed,'status':'visible','created_at':DateTime.now().toIso8601String(),'updated_at':DateTime.now().toIso8601String()});}
  Future<void> recordShare(String contentId,{String target='system'}) async=>_client.from('content_shares').insert({'content_id':contentId,'profile_id':_userId,'share_target':target});
  Future<String> createShareUrl(String contentId) async=>'https://manox.app/content/$contentId';
  Future<String?> signedMediaUrl(String path) async {if(path.startsWith('http://')||path.startsWith('https://'))return path;return _client.storage.from('manox-media').createSignedUrl(path,60*60);}
}
